var S;
var epiColors; // https://github.com/epibyte/p5-epi-colors

function setup() {
	createCanvas(windowWidth, windowHeight);
	frameRate(30);
	ellipseMode(CORNER);
	noStroke();
	fill(212);

	const { EpiColors } = EpiColorsPckg;
	epiColors = new EpiColors();

	initMe();
}
function initMe() {
	shuffle(epiColors.palettes, true);
	S = ~~(max(width, height) / random(2.3, 5.1));
}

function draw() {
	background(16);
	const t = millis() / 1000 / 3;

	for (let y=0, j=0; y<height; j++) {
		const pal = epiColors.palettes[~~(pow(noise(j), 3) * epiColors.palettes.length)];
		const yd = pow(noise(t, j), 1.4) * S;
		for (let x=0, i=0; x<width; i++) {
			const xd = pow(noise(j+t, 5*x/width), 1.8) * S;
			const clr = pal[~~(pow(noise(i+j), 3) * pal.length * 2) % pal.length];
			fill(clr)
			ellipse(x, y, xd, yd);
			x += xd;
		}
		y += yd;
	}
}

function mousePressed() {
	if (!mouseButton.left) return;
	initMe();
}

